import { buildRecords, imageSearch, L, M3D, POOL, type ArchiveRec } from "./archive-kit";
import type { Equipment, Source } from "./types";

/**
 * Expanded lunar archive. Every record is a separately catalogued hardware unit that
 * reached the lunar surface or appears with an explicitly uncertain fate in NASA's inventory — descent stages, impact sites, experiment stations,
 * instruments and international landers. Numbers are the published figures; where a value
 * is unknown the record says so instead of guessing.
 */

