// Apollo 12's S-IVB went into solar orbit, so it is not a lunar surface record.
// Apollo 13 was the first S-IVB deliberately targeted for lunar impact.
const sivbImpacts: ArchiveRec[] = [14, 15, 16, 17].map((n): ArchiveRec => ({
  id: `apollo-${n}-sivb`,
  name: `Apollo ${n} Saturn V Third Stage — Impact Site`,
  short: `S-IVB ${n}`,
  cat: "instrument" as const,
  status: "destroyed" as const,
  imp: "archive" as const,
  mission: `Apollo ${n}`,
  agency: "NASA / Douglas",
  country: "United States",
  years: n >= 16 ? "1972" : n >= 14 ? "1971" : "1969",
  landed: `Lunar impact during Apollo ${n} (${n >= 16 ? "1972" : "1971"})`,
  site: "Lunar surface, impact point determined from seismic data",
  image: POOL.moonCloseup,
  imgKind: "representative" as const,
  imgCaption: "Representative terrain: a fresh crater on the southwest rim of Metius B, imaged by LRO (NASA PIA12915); not this object's landing site.",
  tagline: "An empty rocket stage, aimed at the Moon to make it ring.",
  summary:
    "After the S-IVB pushed Apollo toward the Moon and released the spacecraft, flight controllers targeted the spent stage at the lunar surface. The Apollo seismometers recorded the resulting artificial impact.",
  specs: [["Stage", "Saturn V S-IVB"], ["Propulsion", "One J-2 engine"], ["Outcome", "Deliberate lunar impact"], ["Purpose", "Calibrated seismic source"]],
  instruments: ["Instrument unit", "J-2 engine (spent)", "Propellant tanks"],
  objectives: ["Dispose of the spent stage away from the spacecraft", "Provide a known-mass seismic impulse"],
  disc: [
    ["Reading the Moon's interior", "1970 – 1977", "Timed rocket-stage impacts helped constrain seismic wave speeds in the lunar interior. Core interpretations also depend on much later reanalysis of Apollo recordings."],
    ["Locating the craters", "2010s", "Lunar Reconnaissance Orbiter imagery has identified several S-IVB craters, some within a few kilometres of their predicted coordinates."],
  ],
  what: "The third stage of the Saturn V: a hydrogen tank, an oxygen tank, an instrument unit and a spent J-2 engine.",
  history: "Douglas built the S-IVB rocket stage. Deliberate lunar impact targeting began with Apollo 13; Apollo 12's stage instead entered solar orbit.",
  journey: "After injection it separated from the spacecraft and was commanded onto an impact trajectory rather than being left in a parking orbit.",
  landing: "The stage struck the Moon at high velocity, forming an impact site and producing waves recorded by the Apollo seismic network.",
  fate: "The stage was destroyed as a functioning vehicle. Orbital images can identify impact features, but do not establish the shape of every surviving fragment.",
  legacy: "These impacts are among the best-characterised artificial seismic sources in planetary science.",
  sources: [journal(n), ...SMALL, imageSearch(`Apollo ${n} S-IVB impact`)],
  asset: { kind: "wreck" as const, source: "reconstruction" as const, note: "Schematic impact-hardware illustration, not a measured reconstruction of the crater or surviving fragments.", span: 1.4, height: 0.8 },
  confidence: "reconstruction" as const,
}));

